UPDATE `specialist_profiles` sp
JOIN `users` u
    ON u.id = sp.user_id
JOIN `expertise_categories` c
    ON c.id = sp.category_id
JOIN (
    SELECT 'emily.chen@medlink.local' AS email, 'Pediatrics' AS category_name, 'Dr. Emily Chen is a chief pediatric specialist with over 22 years of clinical practice in pediatric endocrinology and developmental medicine, including prior leadership work at a top-tier tertiary children''s hospital. She provides advanced evaluation and long-term management for growth hormone deficiency, short stature, childhood obesity, insulin resistance, early puberty (precocious puberty), delayed puberty, thyroid dysfunction, and constitutional growth delay. Families also consult her for poor weight gain, feeding concerns, recurrent fatigue, and developmental growth chart deviations. Her care style combines evidence-based protocols with plain-language education so parents can clearly understand complex hormone and metabolism issues. She is known for structured growth tracking, age-adjusted treatment planning, and close coordination with nutrition and rehabilitation teams when needed. Dr. Chen is especially suitable for first-time parents seeking reassurance, children with persistent growth concerns, and adolescents needing a careful transition plan into puberty and long-term metabolic health.' AS bio
    UNION ALL SELECT 'ryan.lin@medlink.local', 'Pediatrics', 'Dr. Ryan Lin is a senior pediatric physician with 15+ years of experience in pediatric respiratory medicine and clinical immunology, and previously served in a major general hospital''s child pulmonary unit. He specializes in childhood asthma, recurrent wheezing, allergic rhinitis (hay fever), chronic bronchitis, viral bronchiolitis, recurrent upper respiratory infections, persistent cough, and exercise-induced breathing symptoms. He also supports families with vaccine planning, catch-up immunization schedules, and post-infection immune recovery guidance. Parents frequently seek his help for nighttime coughing, seasonal allergy flare-ups, school absence due to recurrent colds, and concerns about weak immunity. Dr. Lin emphasizes prevention-first and patient-centered care, combining guideline-based treatment with practical home strategies such as trigger control, inhaler technique coaching, and symptom monitoring plans. He explains medical terms in clear everyday language so caregivers can act confidently between visits. He is ideal for children with frequent respiratory symptoms, allergy-prone families, and parents who want a personalized long-term breathing and vaccination roadmap.' 
    UNION ALL SELECT 'sophie.zhao@medlink.local', 'Pediatrics', 'Dr. Sophie Zhao is an intermediate pediatric specialist focused on adolescent nutrition, digestive health, and behavior-linked growth concerns, with over 10 years of outpatient pediatric experience. Her clinical strengths include undernutrition, childhood obesity, picky eating, functional abdominal pain, constipation, reflux, iron-deficiency anemia, and nutrition support for ADHD and school-related concentration difficulties. She also manages eating behavior concerns, emotional eating patterns, and growth lag associated with unbalanced diets. Dr. Zhao combines structured nutritional assessment with practical family coaching, translating clinical recommendations into realistic meal routines that work for school schedules and home life. She takes a gentle, non-judgmental communication style that helps sensitive children and teenagers engage in care without anxiety. Her approach integrates preventive pediatrics, developmental follow-up, and regular progress checks to ensure sustainable improvement rather than short-term fixes. She is particularly suitable for parents of teenagers with appetite or weight concerns, children with recurring digestive complaints, and families seeking long-term nutrition plans that support both physical growth and emotional wellbeing.' 
    UNION ALL SELECT 'jason.xu@medlink.local', 'Pediatrics', 'Dr. Jason Xu is a junior pediatric doctor providing comprehensive first-line child healthcare with strong training in common acute illnesses and recovery monitoring. He manages recurrent fever, pediatric influenza, viral upper respiratory infections, acute pharyngitis, mild gastroenteritis, dehydration risk in children, common skin rashes, and minor injury follow-up such as sprains and soft-tissue bruises. He also performs routine child health checkups, vaccination status review, growth screening, and school-entry physical guidance. Families value his clear explanations on warning signs, home-care steps, fever management, hydration, and when escalation to emergency care is necessary. Dr. Xu follows a safety-first, family-centered approach that balances evidence-based medicine with practical daily care instructions parents can apply immediately. His consultations are structured and reassuring, with emphasis on early intervention, symptom tracking, and reducing unnecessary anxiety for caregivers. He is a strong fit for families needing dependable general pediatric support, first-time parents navigating frequent childhood infections, and children requiring close but straightforward follow-up after common outpatient conditions.' 
    UNION ALL SELECT 'olivia.wang@medlink.local', 'Dermatology', 'Dr. Olivia Wang is a chief dermatologist with more than 20 years of experience in chronic, autoimmune, and high-complexity skin disease management, including former senior practice at a leading university-affiliated hospital. She specializes in psoriasis, vitiligo, atopic dermatitis, chronic eczema, lupus-related skin manifestations, hidradenitis suppurativa, cutaneous vasculitis, and skin cancer screening for suspicious moles and precancerous lesions. She is highly experienced with biologic therapies, immunomodulatory regimens, and long-term maintenance strategies for relapsing conditions. Patients consult her for persistent itching, recurrent plaques, pigment loss, treatment-resistant inflammation, and difficult diagnosis across overlapping dermatologic disorders. Dr. Wang combines precise clinical diagnostics with empathetic communication, helping patients understand risk, prognosis, and stepwise therapy options in plain terms. Her philosophy centers on durable disease control, quality-of-life restoration, and individualized care pathways that adapt over time. She is especially suitable for patients with chronic or recurrent skin disease, those who have failed prior treatments, and individuals seeking expert long-term management with advanced therapeutic planning.' 
    UNION ALL SELECT 'daniel.sun@medlink.local', 'Dermatology', 'Dr. Daniel Sun is a senior dermatologist with 14+ years of expertise in both medical and cosmetic dermatology, recognized for treating inflammatory and appearance-impacting skin disorders with balanced clinical precision. His core focus includes severe acne, nodulocystic acne, acne scarring, rosacea, seborrheic dermatitis, post-inflammatory hyperpigmentation, sensitive skin inflammation, and recurrent folliculitis. He is also skilled in treatment sequencing with topical and oral medications, chemical peels, scar remodeling plans, and maintenance protocols that minimize relapse. Patients often seek him for persistent breakouts, redness, uneven texture, enlarged pores, and skin barrier instability after prior over-treatment. Dr. Sun uses an outcomes-oriented yet conservative philosophy, prioritizing skin barrier protection and long-term control over short-lived aggressive interventions. He explains treatment timelines, side effects, and realistic expectations in clear language, helping patients stay consistent and confident throughout care. He is ideal for adolescents and adults with stubborn acne patterns, patients needing integrated medical-cosmetic planning, and professionals wanting structured skin recovery with minimal disruption to daily life.' 
    UNION ALL SELECT 'grace.liu@medlink.local', 'Dermatology', 'Dr. Grace Liu is an intermediate dermatologist focused on allergic and reactive skin disorders, with extensive outpatient experience in identifying triggers and stabilizing sensitive skin conditions. She commonly treats contact dermatitis, urticaria (hives), atopic eczema flares, irritant dermatitis, hand eczema, perioral dermatitis, pruritus (persistent itching), and mild photoallergic reactions. Her clinic emphasizes targeted history-taking, patch testing strategies, and trigger mapping for environmental, cosmetic, textile, and workplace exposures. Patients frequently consult her for recurrent redness, burning, itching, rashes after skincare products, and unexplained flare-ups that keep returning despite temporary relief. Dr. Liu follows a barrier-repair-first and prevention-focused approach, combining anti-inflammatory care with practical avoidance and skincare routines suitable for real daily life. She communicates clearly and empathetically, helping patients understand what is happening in the skin and how to prevent recurrence long term. She is particularly suitable for people with sensitive skin, frequent allergy-like rash episodes, and families seeking a systematic plan rather than repeated short-term symptom suppression.' 
    UNION ALL SELECT 'leo.he@medlink.local', 'Dermatology', 'Dr. Leo He is a junior dermatology physician delivering efficient and thorough outpatient care for common skin, hair, and nail concerns, supported by strong frontline dermatology training. He routinely manages fungal infections (tinea), onychomycosis (nail fungus), viral warts, molluscum contagiosum, seborrheic dermatitis, mild eczema, acneiform eruptions, and sudden-onset non-emergency rashes. He also evaluates scalp itching, dandruff-related irritation, and minor skin infections that affect daily comfort and appearance. Patients appreciate his practical consultation style, especially for treatment adherence, hygiene reinforcement, and recurrence prevention in household settings. Dr. He''s approach is straightforward and patient-centered: accurate early assessment, evidence-based first-line therapy, and clear home-care instructions using both medical and everyday language. He emphasizes routine follow-up to confirm treatment response and adjust plans promptly when needed. He is a good choice for patients seeking accessible dermatology care for common conditions, first-time dermatology visits, and individuals who want clear guidance for day-to-day skincare and infection prevention.' 
    UNION ALL SELECT 'michael.zhang@medlink.local', 'Orthopedics', 'Dr. Michael Zhang is a chief orthopedic specialist with over 24 years of surgical and rehabilitation-integrated experience, including prior leadership in spine and joint reconstruction at a major tertiary hospital. His advanced practice covers herniated disc disease, lumbar spinal stenosis, cervical spondylosis, scoliosis, degenerative joint disease, severe osteoarthritis, complex fractures, and revision hip or knee replacement planning. He is known for minimally invasive surgical strategies, perioperative risk optimization, and functional recovery pathways tailored for older adults and medically complex patients. Patients consult him for chronic back pain, nerve compression symptoms, joint deformity, mobility loss, and persistent pain unresponsive to conservative treatment. Dr. Zhang combines surgical precision with patient-centered communication, translating imaging and procedural options into clear decisions families can understand. His philosophy prioritizes safe intervention timing, durable function, and multidisciplinary rehabilitation to restore independence. He is especially suitable for seniors with progressive spine or joint disease, patients considering advanced orthopedic procedures, and families seeking high-level guidance on surgery versus long-term conservative management.' 
    UNION ALL SELECT 'hannah.wu@medlink.local', 'Orthopedics', 'Dr. Hannah Wu is a senior orthopedic and sports medicine physician with 16+ years of experience in lower-limb injury care and return-to-activity rehabilitation. She specializes in ACL tears, meniscal injury, patellofemoral pain (runner''s knee), ankle instability, tendon overuse syndromes, plantar fasciitis, iliotibial band pain, and post-traumatic knee swelling. She also performs ultrasound-guided injections for selected inflammatory and pain conditions as part of structured, non-operative care. Athletes and active adults seek her for recurrent knee pain, training-related overload injuries, instability episodes, and delayed functional recovery after sprains or strains. Dr. Wu''s treatment philosophy is function-first and evidence-driven, combining precise diagnosis, phased rehab programs, movement correction, and injury-prevention coaching. She explains pathology and recovery milestones in practical terms so patients can safely progress without fear of reinjury. She is ideal for runners, gym-goers, and competitive athletes aiming to return to sport, as well as working adults who need reliable pain control and mobility restoration without unnecessary surgery.' 
    UNION ALL SELECT 'kevin.ma@medlink.local', 'Orthopedics', 'Dr. Kevin Ma is an intermediate orthopedic physician focused on metabolic bone health and upper-limb functional disorders, with more than a decade of musculoskeletal clinical experience. His expertise includes osteoporosis, osteopenia, fragility fracture prevention, carpal tunnel syndrome, shoulder impingement, rotator cuff tendinopathy, lateral epicondylitis (tennis elbow), and chronic neck-shoulder overuse pain. He also supports patients with posture-related discomfort, reduced grip strength, and activity-limiting upper extremity stiffness. Dr. Ma provides integrated assessment using clinical examination and risk profiling, then builds practical plans spanning medication review, targeted strengthening, ergonomic correction, and fall-prevention strategies. His philosophy is preventive and patient-centered: detect early deterioration, preserve mobility, and reduce long-term disability through consistent follow-up. He explains musculoskeletal conditions in both technical and plain language, helping patients understand why symptoms recur and how to interrupt that cycle. He is especially suitable for middle-aged and older adults managing bone density decline, desk workers with repetitive strain symptoms, and patients seeking structured non-surgical recovery plans.' 
    UNION ALL SELECT 'ruby.gao@medlink.local', 'Orthopedics', 'Dr. Ruby Gao is a junior orthopedic doctor specializing in general musculoskeletal care, minor trauma follow-up, and rehabilitation coordination. She commonly treats stable minor fractures, ligament sprains, muscle strains, contusions, low-grade tendon irritation, post-cast stiffness, and routine post-operative recovery concerns. She also supports patients with gait discomfort, mild joint swelling, and activity-related pain requiring conservative management and monitoring. Dr. Gao emphasizes clear progression plans that include pain control, safe movement milestones, home exercise guidance, and coordination with physical therapy teams when needed. Patients value her detailed explanations of healing timelines, red-flag symptoms, and practical return-to-work or return-to-school recommendations. Her care model is recovery-focused and collaborative, aiming to restore confidence and daily function while minimizing complications from under- or over-activity. She is a strong fit for patients who need dependable follow-up after minor orthopedic injuries, families supporting rehabilitation at home, and individuals seeking structured, easy-to-follow plans for steady musculoskeletal recovery.' 
    UNION ALL SELECT 'benjamin.li@medlink.local', 'Cardiology', 'Dr. Benjamin Li is a chief cardiologist with over 25 years of experience in complex cardiovascular medicine, including previous senior roles at a top-tier cardiac center. His primary expertise includes coronary artery disease, heart failure, resistant hypertension (high blood pressure), dyslipidemia, stable angina, post-myocardial infarction care, post-stent management, and age-related cardiovascular risk optimization. He is frequently consulted for chest tightness, exertional dyspnea, edema, blood pressure variability, and recurrent cardiovascular risk concerns in multi-morbidity patients. Dr. Li delivers evidence-based and prevention-oriented care that combines advanced risk stratification with practical long-term planning across medication, lifestyle, and follow-up testing. He is known for translating complex cardiac data into clear treatment priorities that patients and families can understand and act on. His philosophy centers on continuity, early decompensation detection, and individualized targets to reduce hospitalization and preserve quality of life. He is especially suitable for older adults with multiple cardiac risk factors, patients transitioning after stent or hospitalization, and families seeking expert long-horizon management of chronic heart disease.' 
    UNION ALL SELECT 'chloe.deng@medlink.local', 'Cardiology', 'Dr. Chloe Deng is a senior cardiology specialist in rhythm disorders with over 14 years of electrophysiology-focused clinical practice. She manages atrial fibrillation (AFib), supraventricular tachycardia, symptomatic palpitations, premature beats, sinus node dysfunction, bradycardia, post-ablation rhythm surveillance, and pacemaker follow-up optimization. She also supports stroke risk assessment and anticoagulation counseling for patients with arrhythmia-related thromboembolic risk. Patients commonly seek her for irregular heartbeat episodes, dizziness, unexplained fatigue, intermittent chest fluttering, and anxiety linked to recurrent rhythm symptoms. Dr. Deng combines precise ECG and ambulatory rhythm interpretation with patient-centered communication, ensuring each person understands triggers, warning signs, and treatment options in plain terms. Her clinical philosophy balances rhythm control, rate control, and quality-of-life goals while minimizing unnecessary interventions. She is particularly suitable for adults with recurrent palpitations, patients requiring long-term AFib monitoring, and individuals with pacemakers who need consistent, specialist-led follow-up and stroke prevention planning.' 
    UNION ALL SELECT 'ethan.qiu@medlink.local', 'Cardiology', 'Dr. Ethan Qiu is an intermediate cardiology physician focused on preventive cardiology and vascular risk control, with broad experience in outpatient heart assessment and longitudinal monitoring. His clinical scope includes chronic hypertension (high blood pressure), prehypertension, atypical chest pain differentiation, early coronary risk screening, dyslipidemia, metabolic syndrome, stress-related heart symptoms, and ECG interpretation for routine and follow-up care. He helps patients investigate palpitations, exertional discomfort, and blood pressure instability before these patterns progress into advanced disease. Dr. Qiu follows a prevention-first, data-guided philosophy that combines medication optimization with realistic lifestyle interventions in nutrition, activity, sleep, and stress management. He is known for clear explanations that bridge medical language and practical daily steps, making treatment plans sustainable for busy working adults and families. He is especially suitable for patients with early cardiovascular risk factors, office workers with borderline but persistent abnormalities, and anyone seeking a structured roadmap to reduce future heart attack and stroke risk through consistent long-term care.' 
    UNION ALL SELECT 'mia.tang@medlink.local', 'Cardiology', 'Dr. Mia Tang is a junior cardiovascular physician providing accessible and structured first-line heart care for patients in early-stage or routine management phases. She commonly evaluates mild hypertension, borderline cholesterol concerns, non-emergency chest discomfort, exertional shortness of breath, occasional palpitations, family-history-based cardiovascular risk, and baseline ECG abnormalities that require clinical correlation. Her clinic also supports routine heart checkups, preventive counseling, and follow-up planning for individuals beginning long-term cardiovascular care. Dr. Tang''s approach is patient-friendly and proactive: she combines guideline-based screening with practical coaching on diet, exercise, weight control, sleep hygiene, and home blood pressure tracking. Patients value her clear, calm explanations of what findings are urgent versus monitorable, which reduces uncertainty and supports better adherence. She is a strong fit for first-time cardiology patients, younger adults with newly identified risk factors, and families who want consistent preventive guidance to maintain long-term heart health before serious complications emerge.' 
    UNION ALL SELECT 'isabella.zhou@medlink.local', 'Psychiatry', 'Dr. Isabella Zhou is a chief psychiatrist with over 20 years of clinical psychiatry leadership, including previous work at a major mental health center managing complex and treatment-resistant cases. She specializes in major depressive disorder, bipolar disorder, generalized anxiety disorder, panic disorder, chronic insomnia, obsessive-compulsive symptoms, and comorbid mood-sleep presentations. Her expertise includes difficult medication optimization, side-effect balancing, relapse prevention, and staged treatment strategies for patients who have not improved with prior regimens. Patients consult her for persistent low mood, loss of motivation, emotional instability, sleep disruption, somatic anxiety symptoms, and recurrent episodes that affect family and work functioning. Dr. Zhou uses a compassionate, structured, and evidence-based model that combines diagnostic precision with clear shared decision-making. She emphasizes dignity, continuity, and individualized recovery goals while coordinating psychotherapy referral when appropriate. She is especially suitable for adults with complex mood disorders, patients needing high-level medication strategy review, and families seeking stable long-term psychiatric care with strong clinical oversight.' 
    UNION ALL SELECT 'noah.yu@medlink.local', 'Psychiatry', 'Dr. Noah Yu is a senior psychiatrist with 15+ years of experience focused on anxiety-spectrum and stress-related conditions across working adults and young professionals. He treats generalized anxiety disorder, panic attacks, adjustment disorder, burnout-related insomnia, health anxiety, somatic tension symptoms, social anxiety features, and mixed anxiety-depressive presentations. He is skilled in integrating pharmacologic treatment with structured symptom review, functional monitoring, and practical coping plans for high-pressure life contexts. Patients often seek him for persistent overthinking, chest tightness linked to stress, poor concentration, irritability, sleep fragmentation, and performance decline at work or school. Dr. Yu''s treatment philosophy is collaborative and stepwise, using measurable goals, clear medication counseling, and behavioral stabilization strategies to restore day-to-day functioning. He communicates in grounded, non-stigmatizing language that helps patients feel understood and empowered. He is particularly suitable for people facing chronic stress, panic episodes, or workplace burnout, and for patients who want balanced psychiatric care combining symptom relief with durable resilience-building.' 
    UNION ALL SELECT 'vivian.feng@medlink.local', 'Psychiatry', 'Dr. Vivian Feng is an intermediate psychiatry specialist with strong focus on women''s mental health, emotional regulation, and relationship-linked psychological stress. Her clinical scope includes postpartum depression, perinatal anxiety, premenstrual mood worsening, adjustment difficulties, relational distress, mild-to-moderate depressive symptoms, sleep disturbance, and caregiver fatigue. She provides structured psychological assessment and longitudinal follow-up to detect early deterioration and support timely intervention. Patients appreciate her calm, empathetic style when discussing sensitive topics such as identity transition into parenthood, family conflict, emotional overwhelm, and guilt-related thought patterns. Dr. Feng practices person-centered, trauma-aware care that combines psychiatric evaluation with practical coping frameworks and coordinated referral for psychotherapy when indicated. She uses clear language and actionable plans so patients and families can track progress without confusion. She is especially suitable for women navigating postpartum emotional changes, patients managing family-related stress, and individuals seeking compassionate, structured support for mood and relationship challenges in everyday life.' 
    UNION ALL SELECT 'lucas.ren@medlink.local', 'Psychiatry', 'Dr. Lucas Ren is a junior mental health physician providing early-stage psychiatric support for common, non-emergency emotional and stress-related concerns. He commonly manages mild anxiety, adjustment disorder, situational insomnia, stress-related irritability, concentration decline under pressure, low-mood episodes, and subclinical panic-like symptoms requiring early intervention and monitoring. His consultations focus on symptom clarification, risk screening, and practical next steps before problems become entrenched. Dr. Ren emphasizes supportive, low-stigma care that combines psychoeducation, sleep hygiene planning, stress reduction techniques, and mindfulness-based self-regulation resources. Patients value his clear explanations of symptom patterns, recovery timelines, and when specialist escalation is appropriate. His philosophy centers on early engagement, realistic goal-setting, and continuity so patients build confidence in managing their mental health over time. He is a strong fit for students, young professionals, and first-time psychiatry patients who want approachable guidance, structured follow-up, and a safe space to start addressing anxiety, stress, and sleep disruption.' 
    UNION ALL SELECT 'victoria.jiang@medlink.local', 'Gynecology', 'Dr. Victoria Jiang is a chief gynecology specialist in reproductive endocrinology with more than 21 years of experience, including advanced practice in infertility and hormonal disorders at a high-volume women''s health center. She specializes in polycystic ovary syndrome (PCOS), endometriosis, irregular menstruation, ovulatory dysfunction, luteal phase concerns, infertility workup, recurrent implantation challenges, and complex hormonal imbalance affecting fertility and quality of life. She is frequently consulted for pelvic pain, cycle unpredictability, acne-hormonal links, weight-related endocrine disruption, and preconception planning. Dr. Jiang''s care philosophy is precise and patient-centered: she integrates diagnostic depth with clear explanation so patients understand options across medical therapy, timing strategies, and long-term reproductive planning. She emphasizes continuity, individualized hormone management, and shared decision-making for both natural conception pathways and assisted fertility coordination when needed. She is especially suitable for women trying to conceive, patients with chronic cycle or ovulation problems, and couples seeking expert, compassionate guidance through structured reproductive care.' 
    UNION ALL SELECT 'eric.luo@medlink.local', 'Gynecology', 'Dr. Eric Luo is a senior gynecology physician with 17+ years of women''s health experience focused on menopausal care, preventive screening, and chronic gynecologic monitoring. His expertise includes perimenopausal symptoms, menopause-related vasomotor complaints, sleep disturbance linked to hormonal transition, cervical screening (Pap smear) follow-up, uterine fibroid surveillance, abnormal uterine bleeding evaluation, vaginal atrophy symptoms, and bone-health risk awareness in midlife women. Patients commonly seek him for hot flashes, mood and sleep changes, cycle irregularity, pelvic pressure, and long-term preventive planning. Dr. Luo combines evidence-based gynecology with clear, respectful communication, helping patients understand test results, risk levels, and treatment choices in practical language. His philosophy is preventive and quality-of-life oriented, balancing symptom relief with long-term health protection through consistent follow-up. He is especially suitable for women in perimenopause or menopause, patients requiring regular cervical and uterine monitoring, and those wanting a stable specialist partnership for healthy aging and sustained wellbeing.' 
    UNION ALL SELECT 'ava.shen@medlink.local', 'Gynecology', 'Dr. Ava Shen is an intermediate gynecology specialist dedicated to prenatal monitoring and routine reproductive health management, with over 11 years of clinical women''s health practice. She commonly treats early pregnancy concerns, first-trimester symptom monitoring, vulvovaginal candidiasis (yeast infection), bacterial vaginosis, pelvic inflammatory disease (PID), menstrual discomfort, cervicitis follow-up, and recurrent lower genital tract infection prevention. She also supports patients with preconception counseling, routine screening, and education on warning signs that require urgent escalation. Dr. Shen''s style is educational and reassuring: she explains diagnoses and treatment options in straightforward language while tailoring plans to each patient''s life stage and fertility goals. Her philosophy emphasizes preventive care, treatment adherence, and continuity to reduce recurrence and protect long-term reproductive health. She is particularly suitable for women planning pregnancy, patients needing careful early prenatal follow-up, and individuals seeking dependable gynecologic care that blends clinical thoroughness with empathetic communication.' 
    UNION ALL SELECT 'nicole.xie@medlink.local', 'Gynecology', 'Dr. Nicole Xie is a junior gynecology physician focused on general outpatient women''s health, especially for adolescents and young adults attending gynecology for the first time. Her clinical scope includes dysmenorrhea (painful periods), irregular menstrual cycles, premenstrual syndrome, contraceptive counseling, routine annual exams, mild vaginal infections, HPV prevention education, and non-emergency pelvic discomfort assessment. She helps patients navigate early reproductive health decisions with clear explanations on options, side effects, and expected outcomes. Dr. Xie practices a respectful and privacy-centered approach, creating a safe and non-judgmental environment for discussing sensitive symptoms and lifestyle concerns. She combines evidence-based guidance with practical self-care plans covering cycle tracking, pain management, hygiene habits, and follow-up timing. She is especially suitable for first-time gynecology visitors, students and young professionals needing reliable contraception advice, and patients seeking approachable long-term support for routine menstrual and reproductive health needs.' 
) seed
    ON seed.email = u.email
   AND seed.category_name = c.category_name
SET sp.`bio` = seed.bio
WHERE u.email LIKE '%@medlink.local';
